<?php

declare(strict_types=1);

namespace TCM\Core;

/** Curated beginner-to-advanced interview questions for every public Learn guide. */
final class InterviewPrepCatalog
{
    /** @return array<string, array<string, mixed>> */
    public static function forGuides(array $guides): array
    {
        $questions = [
            'python' => [
                ['question' => 'What is the difference between a list and a tuple?', 'level' => 'Beginner', 'answer' => 'Both keep an ordered group of values. A list can be changed after it is created; a tuple is normally used for a fixed group that should not be changed. Choose based on whether the collection needs to be editable.', 'say' => '“I use a list for values that may change, such as a task queue. I use a tuple for a fixed record, such as coordinates. Both keep order, but lists are mutable and tuples are immutable.”', 'code' => "topics = ['Python', 'HTML']\ntopics.append('CSS')\n\npoint = (10, 20)\n# point[0] = 5  # TypeError: tuple items cannot be reassigned", 'note' => 'The list changes in place; the tuple gives an error if you try to replace one of its items.'],
                ['question' => 'What is a Python dictionary, and when would you use one?', 'level' => 'Beginner', 'answer' => 'A dictionary stores values under unique keys. It is useful when you want to look up a value by a meaningful name or identifier instead of remembering its position in a list.', 'say' => '“A dictionary maps keys to values. I use it when each value has a label, like a user ID mapped to a profile or a product name mapped to a price.”', 'code' => "course = {'name': 'Python', 'minutes': 30}\nprint(course['name'])\ncourse['minutes'] = 45", 'note' => 'Here name and minutes are clearer than remembering that the course title is item zero.'],
                ['question' => 'Why do Python functions use return instead of print for results?', 'level' => 'Intermediate', 'answer' => 'return sends a value back to the code that called the function, so that code can store it, combine it or test it. print only displays text for a person and does not give the caller a reusable result.', 'say' => '“I return a result when other code needs to use it. I print only when I want to show a message, usually at the user interface or command-line boundary.”', 'code' => "def total_with_tax(price, rate):\n    return price * (1 + rate)\n\namount = total_with_tax(100, 0.18)\nprint(amount)", 'note' => 'The calculation can be reused in another function or a test because it returns a number.'],
                ['question' => 'What is a Python generator, and why can it save memory?', 'level' => 'Advanced', 'answer' => 'A generator provides one value at a time when the caller requests the next value. It does not need to build and keep a complete result list in memory, which helps when processing a large input.', 'say' => '“A generator is a lazy iterable. It produces each value on demand, so I can process a large stream without holding every result at once.”', 'code' => "def squares(numbers):\n    for number in numbers:\n        yield number * number\n\nfor square in squares(range(3)):\n    print(square)", 'note' => 'yield pauses the function and resumes it when the loop asks for the next square.'],
            ],
            'html' => [
                ['question' => 'What is semantic HTML, and why does it matter?', 'level' => 'Beginner', 'answer' => 'Semantic HTML uses elements that describe the purpose of their content, such as nav, main, article and button. Browsers, search engines and assistive technology can understand the page structure more reliably than a page made only from generic div elements.', 'say' => '“I choose an element for its meaning first. Semantic landmarks make a page easier to navigate and give assistive technology useful structure; CSS can still control how it looks.”', 'code' => "<header><a href=\"/\">Study Hub</a></header>\n<nav aria-label=\"Main navigation\">\n  <a href=\"/learn\">Learn</a>\n</nav>\n<main><article><h1>HTML basics</h1></article></main>", 'note' => 'The elements describe page roles; they are not just visual containers.'],
                ['question' => 'When should you use a button and when should you use a link?', 'level' => 'Beginner', 'answer' => 'A link navigates to another address or page section. A button performs an action on the current page, such as submitting a form or opening a dialog. Using the right element gives users expected keyboard and assistive-technology behavior.', 'say' => '“If the user is going somewhere, I use an anchor with an href. If the user is asking the page to do something, I use a button.”', 'code' => "<a href=\"/courses\">Browse courses</a>\n<button type=\"button\" id=\"open-help\">Open help</button>", 'note' => 'The link has a destination; the button performs an action.'],
                ['question' => 'How do you make an HTML form field accessible?', 'level' => 'Intermediate', 'answer' => 'Give each input a visible label connected using matching for and id values. Explain required formats and errors in text, use the correct input type, and do not use placeholder text as the only label.', 'say' => '“I associate a real label with every control, choose a useful input type, and show instructions or validation errors in text so the field works for keyboard and screen-reader users too.”', 'code' => "<label for=\"email\">Email address</label>\n<input id=\"email\" name=\"email\" type=\"email\" required>", 'note' => 'Clicking the label focuses the input, and its name is announced to assistive technology.'],
                ['question' => 'What is the purpose of alt text on an image?', 'level' => 'Intermediate', 'answer' => 'Alt text communicates the useful information in an image when the image cannot be seen or loaded. Decorative images should normally use empty alt text so screen readers can skip them. The description should fit the image’s purpose in that page, not repeat nearby text.', 'say' => '“I write alt text for informative images and leave it empty for decoration. I describe the information the image adds, not every visual detail.”', 'code' => "<img src=\"team-chart.png\" alt=\"Support requests fell each month from January to March\">\n<img src=\"divider.svg\" alt=\"\">", 'note' => 'The first image conveys data; the decorative divider adds no information.'],
            ],
            'css' => [
                ['question' => 'Explain the CSS box model.', 'level' => 'Beginner', 'answer' => 'Every element is laid out as content surrounded by padding, a border and margin. By default, a declared width applies to the content only. With border-box, the declared width includes padding and border, which makes responsive sizing easier to reason about.', 'say' => '“The box model is content, padding, border and margin. I usually use box-sizing: border-box so the width I declare includes the inner spacing and border.”', 'code' => "*, *::before, *::after {\n  box-sizing: border-box;\n}\n\n.card { width: 100%; padding: 1rem; border: 1px solid #ccc; }", 'note' => 'The card stays within its parent width instead of growing by the padding and border amount.'],
                ['question' => 'When would you choose Flexbox instead of CSS Grid?', 'level' => 'Beginner', 'answer' => 'Flexbox is designed to arrange items primarily along one direction at a time, such as a row of controls. Grid is designed to coordinate rows and columns together. They can work together; choose the one that matches the relationship between the items.', 'say' => '“I use Flexbox for a one-dimensional alignment, like a toolbar. I use Grid when I need to control both columns and rows, like a dashboard.”', 'code' => ".toolbar { display: flex; align-items: center; gap: 1rem; }\n\n.dashboard { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }", 'note' => 'The toolbar flows in one line; the dashboard defines a two-column structure.'],
                ['question' => 'What is CSS specificity?', 'level' => 'Intermediate', 'answer' => 'Specificity is part of how the browser decides which matching rule wins when declarations conflict. In general, an ID selector outweighs a class selector, which outweighs an element selector. The cascade also considers origin, importance and source order, so adding more selectors is not always the right fix.', 'say' => '“Specificity helps resolve competing selectors. I keep selectors simple and use component classes so the cascade stays predictable instead of escalating selector weight.”', 'code' => ".card { color: #222; }\n.featured { color: #0759a5; }\n/* Both are class selectors; if both match, later cascade rules apply. */", 'note' => 'A single class is easier to override safely than a long chain of nested selectors.'],
                ['question' => 'How do media queries help create responsive layouts?', 'level' => 'Intermediate', 'answer' => 'A media query applies styles when a condition such as viewport width or user preference matches. A responsive layout should adapt to the available space and keep content readable, rather than merely target a list of device names.', 'say' => '“I start with a flexible layout, then use a media query when the content needs a different arrangement at a particular width. I also check zoom and keyboard focus.”', 'code' => ".cards { display: grid; grid-template-columns: 1fr; gap: 1rem; }\n\n@media (min-width: 48rem) {\n  .cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n}", 'note' => 'Small screens get one column; when there is enough width, cards use two columns.'],
            ],
            'bootstrap' => [
                ['question' => 'What is Bootstrap, and what does its grid system do?', 'level' => 'Beginner', 'answer' => 'Bootstrap is a front-end toolkit with CSS, components and optional JavaScript behavior. Its grid uses containers, rows and responsive columns to arrange content at defined breakpoints. It speeds up common interface work, but it does not replace semantic HTML or accessibility checks.', 'say' => '“Bootstrap gives a project a consistent starting system. The grid lets me arrange columns responsively, while I still choose meaningful markup and verify that the page works for users.”', 'code' => "<div class=\"container\">\n  <div class=\"row\">\n    <main class=\"col-12 col-md-8\">Article</main>\n    <aside class=\"col-12 col-md-4\">Related links</aside>\n  </div>\n</div>", 'note' => 'Below the medium breakpoint both columns span the row; at wider sizes they use eight and four grid columns.'],
                ['question' => 'How do Bootstrap responsive breakpoints work?', 'level' => 'Intermediate', 'answer' => 'Responsive class infixes apply styles at a breakpoint and larger widths. For example, col-12 applies at all widths while col-md-6 takes effect from the medium breakpoint upward. The exact breakpoint values belong to the Bootstrap version and can be customized in a Sass build.', 'say' => '“Bootstrap’s breakpoint infix applies a layout from that width upward. I use the smallest layout as a base, then add breakpoint classes where the content needs more columns.”', 'code' => "<div class=\"col-12 col-lg-6\">\n  Half-width from the large breakpoint upward\n</div>", 'note' => 'The column uses the full row first, then half the row on larger screens.'],
                ['question' => 'What is the difference between a Bootstrap utility and a component?', 'level' => 'Intermediate', 'answer' => 'A utility class applies a small focused style such as spacing, display or text alignment. A component combines markup and styles into a repeated interface pattern such as a card or alert. Utilities are quick for small adjustments; repeated complex patterns are clearer as named components.', 'say' => '“A utility is one small styling choice; a component is a reusable UI pattern. I use utilities for simple layout adjustments and components for consistent repeated structures.”', 'code' => "<article class=\"card h-100\">\n  <div class=\"card-body d-flex flex-column\">\n    <h2 class=\"h5 card-title\">Java</h2>\n    <a class=\"btn btn-primary mt-auto\" href=\"/learn/java\">Open guide</a>\n  </div>\n</article>", 'note' => 'card is the component pattern; h-100, d-flex and mt-auto are individual utilities.'],
                ['question' => 'Why should Bootstrap components still be checked for accessibility?', 'level' => 'Advanced', 'answer' => 'A framework can provide useful defaults but cannot know whether a page’s labels, heading order, keyboard flow and content are correct. Interactive components need the right JavaScript, accessible names and state behavior. Test with keyboard and assistive technology instead of assuming a class name guarantees accessibility.', 'say' => '“Bootstrap helps with implementation, but accessibility depends on how I use it. I verify labels, focus behavior, contrast and component state in the finished interface.”', 'code' => "<button class=\"btn btn-primary\" type=\"button\"\n        aria-expanded=\"false\" aria-controls=\"help-panel\">\n  Show help\n</button>\n<div id=\"help-panel\" hidden>Keyboard tips</div>", 'note' => 'An interactive control should expose its state and identify the content it controls.'],
            ],
            'scss' => [
                ['question' => 'What is Sass, and how is SCSS different from CSS?', 'level' => 'Beginner', 'answer' => 'Sass is a stylesheet language with features such as variables, mixins and modules. SCSS is its CSS-like syntax: most valid CSS can be written in an SCSS file. A build step compiles SCSS into standard CSS that browsers can use.', 'say' => '“SCSS is Sass written with CSS-style braces and semicolons. It adds authoring features, then a compiler turns the result into browser-ready CSS.”', 'code' => "\$brand: #1458a6;\n\n.button {\n  color: white;\n  background: \$brand;\n}", 'note' => 'The Sass variable is replaced during compilation; it is not a browser runtime variable.'],
                ['question' => 'When should you use a Sass mixin?', 'level' => 'Intermediate', 'answer' => 'A mixin packages reusable declarations and can accept parameters. It is useful when a group of styles repeats and should stay consistent. Avoid creating a mixin for every tiny rule; Sass functions are more suitable for calculations that return a value.', 'say' => '“I use a mixin for reusable groups of declarations, especially when a few options change. If I only need a computed value, I use a function instead.”', 'code' => "@mixin focus-ring(\$color) {\n  outline: 3px solid \$color;\n  outline-offset: 2px;\n}\n\n.button:focus-visible {\n  @include focus-ring(#1458a6);\n}", 'note' => 'One shared focus style can be reused while each include can supply its own color.'],
                ['question' => 'Why use Sass modules with @use instead of old @import?', 'level' => 'Intermediate', 'answer' => '@use loads a Sass module with a namespace, so it makes dependencies explicit and avoids placing every variable and mixin into one global scope. @forward can expose selected module members from a package entry point. This makes larger style systems easier to maintain.', 'say' => '“I use @use to import a module through a clear namespace. That reduces naming collisions and makes it easier to see where a token or mixin comes from.”', 'code' => "// _tokens.scss\n\$brand: #1458a6;\n\n// button.scss\n@use 'tokens';\n.button { background: tokens.\$brand; }", 'note' => 'The tokens namespace tells you exactly which module owns the value.'],
                ['question' => 'How are Sass variables different from CSS custom properties?', 'level' => 'Advanced', 'answer' => 'Sass variables are resolved while the stylesheet is compiled. CSS custom properties remain in the generated CSS and can change at runtime, inherit through the DOM and respond to themes. Use Sass for build-time organization and custom properties when the browser needs to switch values dynamically.', 'say' => '“Sass variables help while building the CSS. Custom properties exist in the browser, so they are better for runtime theming or values that change by element.”', 'code' => "\$brand-at-build: #1458a6;\n:root { --brand: #{\$brand-at-build}; }\n\n.dark-theme { --brand: #8bb8ff; }\n.button { background: var(--brand); }", 'note' => 'Sass inserts the initial color; the CSS custom property can then change with the theme.'],
            ],
            'java' => [
                ['question' => 'What is the difference between the JDK, JVM and Java bytecode?', 'level' => 'Beginner', 'answer' => 'The JDK is the developer kit with tools such as the compiler. The compiler turns Java source into bytecode. The JVM runs that bytecode on a platform, which is why a compiled Java program can run on compatible systems with a JVM.', 'say' => '“I write source code and compile it with the JDK into bytecode. The JVM executes that bytecode on the target machine.”', 'code' => "// Compile source\njavac Hello.java\n\n// Run the generated bytecode\njava Hello", 'note' => 'javac produces a .class file; java starts it using the Java Virtual Machine.'],
                ['question' => 'What is encapsulation in object-oriented programming?', 'level' => 'Beginner', 'answer' => 'Encapsulation keeps an object’s internal state behind a clear interface. A class controls how its state changes, which helps stop callers from putting the object into an invalid condition. It is not simply making every field private; the public methods should express useful behavior.', 'say' => '“Encapsulation means an object protects its own state and exposes deliberate operations. I validate changes at that boundary so callers cannot bypass the class rules.”', 'code' => "final class Counter {\n    private int value;\n\n    public void increment() { value++; }\n    public int value() { return value; }\n}", 'note' => 'Other code can increment the counter or read it, but cannot directly assign an arbitrary value.'],
                ['question' => 'When would you use an interface in Java?', 'level' => 'Intermediate', 'answer' => 'An interface defines behavior that different classes can provide. Code can depend on that behavior instead of one concrete implementation, which makes alternatives easier to substitute and tests easier to isolate. Use an interface when there is a real boundary or more than one useful implementation, not automatically for every class.', 'say' => '“I use an interface to express a capability or dependency boundary. The caller uses the contract, so implementations can change without rewriting the caller.”', 'code' => "interface Notifier { void send(String message); }\n\nfinal class Reminder {\n    private final Notifier notifier;\n    Reminder(Notifier notifier) { this.notifier = notifier; }\n    void remind() { notifier.send(\"Study today\"); }\n}", 'note' => 'Reminder only needs something that can send a message; it does not need to know the delivery method.'],
                ['question' => 'How do List, Set and Map differ?', 'level' => 'Beginner', 'answer' => 'A List keeps items in sequence and can contain duplicates. A Set represents unique members. A Map associates keys with values so you can look up a value by its key. Pick the structure based on the questions the program needs to answer.', 'say' => '“I use List for an ordered sequence, Set when membership must be unique, and Map when I need to find a value by a key.”', 'code' => "List<String> order = new ArrayList<>();\nSet<String> unique = new HashSet<>();\nMap<String, Integer> minutes = new HashMap<>();\nminutes.put(\"loops\", 25);", 'note' => 'Each collection models a different rule about ordering, uniqueness or lookup.'],
            ],
            'spring-boot' => [
                ['question' => 'What is Spring Boot, and how is it different from Spring Framework?', 'level' => 'Beginner', 'answer' => 'Spring Framework provides building blocks for Java applications, including dependency injection and web support. Spring Boot uses those building blocks with conventions, dependency starters and auto-configuration so an application can start with less manual setup. Boot complements Java and Spring; it does not replace them.', 'say' => '“Spring Framework provides the core application tools. Spring Boot adds convenient defaults and an application launcher, so I can build and run a Spring application with less configuration.”', 'code' => "@SpringBootApplication\npublic class StudyApplication {\n    public static void main(String[] args) {\n        SpringApplication.run(StudyApplication.class, args);\n    }\n}", 'note' => 'The main method starts Spring and the embedded server using the project configuration.'],
                ['question' => 'What is dependency injection in Spring?', 'level' => 'Intermediate', 'answer' => 'Dependency injection means a class receives the collaborators it needs instead of constructing them itself. Spring manages application objects called beans and supplies dependencies through constructors or other supported injection points. Constructor injection makes requirements explicit and makes unit tests easier to set up.', 'say' => '“A service declares what it needs in its constructor. Spring provides those dependencies when it creates the service, which keeps construction and business logic separate.”', 'code' => "@Service\nclass CourseService {\n    private final CourseRepository repository;\n\n    CourseService(CourseRepository repository) {\n        this.repository = repository;\n    }\n}", 'note' => 'The service does not call new CourseRepository(); Spring supplies the repository bean.'],
                ['question' => 'What does @SpringBootApplication do?', 'level' => 'Intermediate', 'answer' => '@SpringBootApplication combines application configuration, auto-configuration and component scanning. Scanning normally begins in the package containing the main class and includes its child packages. Putting controllers and services under that root package helps Spring discover them.', 'say' => '“It marks the application entry point, enables Boot’s conditional defaults and tells Spring where to find application components.”', 'code' => "package in.tcm.study;\n\n@SpringBootApplication\npublic class StudyApplication {\n    public static void main(String[] args) {\n        SpringApplication.run(StudyApplication.class, args);\n    }\n}", 'note' => 'A controller in in.tcm.study.api is under the root package, so component scanning can find it.'],
                ['question' => 'Why separate controller, service and repository responsibilities?', 'level' => 'Intermediate', 'answer' => 'A controller handles HTTP details, a service coordinates application rules, and a repository handles persistence. The separation keeps each class focused and allows business rules to be tested without sending a web request or connecting to a real database. Keep the design proportional to the application rather than adding empty layers.', 'say' => '“The controller translates the request, the service applies the use-case rules, and the repository loads or saves data. Each layer has one clear reason to change.”', 'code' => "@RestController\nclass CourseController {\n    private final CourseService service;\n    CourseController(CourseService service) { this.service = service; }\n\n    @GetMapping(\"/api/courses\")\n    List<CourseDto> all() { return service.findAll(); }\n}", 'note' => 'The HTTP handler delegates the actual use case rather than implementing database and business rules itself.'],
            ],
            'github-cicd' => [
                ['question' => 'What is the difference between CI and CD?', 'level' => 'Beginner', 'answer' => 'Continuous integration (CI) automatically builds and checks changes so teams find problems early. Continuous delivery (CD) keeps a tested change ready to release, usually with an approval step. Continuous deployment goes further and automatically releases every change that passes its checks.', 'say' => '“CI verifies changes continuously. Delivery keeps a verified release ready; deployment automatically sends passing changes to users.”', 'code' => "name: checks\non:\n  pull_request:\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: echo \"Run project checks here\"", 'note' => 'The pull request event starts an automated job before the code is merged.'],
                ['question' => 'What is a GitHub Actions workflow, and what triggers it?', 'level' => 'Beginner', 'answer' => 'A workflow is a YAML file stored in .github/workflows. Its on section lists events such as a push, pull request or manual dispatch that start the workflow. A workflow contains jobs, and each job runs steps on a runner.', 'say' => '“A workflow is an automation recipe. The event starts it, a runner executes its jobs, and steps perform the build, test or deployment actions.”', 'code' => "name: test\non:\n  push:\n    branches: [main]\njobs:\n  verify:\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo \"Verify the app\"", 'note' => 'A push to main starts the verify job on a temporary GitHub-hosted runner.'],
                ['question' => 'How should you protect credentials used by a workflow?', 'level' => 'Intermediate', 'answer' => 'Store credentials as GitHub Actions secrets or environment secrets, then pass them only to the step that needs them. Never commit secrets to the repository or print them in logs. Limit token permissions and use protected environments for sensitive deployments.', 'say' => '“I keep credentials in GitHub’s secret store, scope access to the smallest job, avoid logging them and restrict deployment permissions.”', 'code' => "permissions:\n  contents: read\n\nsteps:\n  - name: Deploy\n    env:\n      DEPLOY_TOKEN: \${{ secrets.DEPLOY_TOKEN }}\n    run: ./deploy.sh", 'note' => 'The token comes from repository settings at runtime, not from a value committed in the YAML file.'],
                ['question' => 'Why use artifacts in a CI/CD workflow?', 'level' => 'Advanced', 'answer' => 'An artifact is a file produced by a workflow that can be retained or passed to another job. For example, one job can build a site and upload its output; a deployment job can download and publish that exact build. This avoids rebuilding different files at each stage.', 'say' => '“Artifacts let workflow jobs share the build output. I can test and deploy the same generated files, which makes the release process easier to trace.”', 'code' => "- uses: actions/upload-artifact@v4\n  with:\n    name: site-build\n    path: dist/", 'note' => 'The generated dist folder is saved as an artifact for a later workflow job.'],
            ],
        ];

        $catalog = [];
        foreach ($guides as $slug => $guide) {
            $catalog[$slug] = [
                'name' => (string) ($guide['name'] ?? ucfirst($slug)),
                'summary' => (string) ($guide['summary'] ?? ''),
                'questions' => $questions[$slug] ?? self::starterQuestions($guide),
            ];
        }

        return $catalog;
    }

    /** @param array<string,mixed> $guide
     *  @return list<array<string,string>>
     */
    private static function starterQuestions(array $guide): array
    {
        $name = (string) ($guide['name'] ?? 'this topic');
        $summary = (string) ($guide['summary'] ?? '');
        $firstLesson = $guide['lessons'][0] ?? [];
        $firstTitle = (string) ($firstLesson['title'] ?? 'the first concept');
        $firstExplanation = (string) ($firstLesson['explanation'] ?? 'Start with the basic concepts and build a small example.');
        $firstExample = (string) ($firstLesson['example'] ?? '// Add a small example from the guide.');

        return [[
            'question' => 'What is ' . $name . ' used for?',
            'level' => 'Beginner',
            'answer' => $summary,
            'say' => '“' . $name . ' helps with ' . lcfirst($summary) . ' I would start by understanding ' . preg_replace('/^\d+\.\s*/', '', $firstTitle) . '.”',
            'code' => $firstExample,
            'note' => $firstExplanation,
        ]];
    }
}
